fn put(out:&mut[u8],at:usize,x:f64){out[at..at+8].copy_from_slice(&x.to_le_bytes());}
#[no_mangle]
pub unsafe extern "C" fn gram_schmidt(v:*const i64,n:usize,out:*mut u8,cap:usize)->i64{if v.is_null()||n<2||n>18{return -1}let x=std::slice::from_raw_parts(v,n);let(r,d)=(x[0],x[1]);if !(1..=4).contains(&r)||d<r||d>4||n!=2+(r*d)as usize{return -1}let mut a=[[0.0f64;4];4];let mut q=[[0.0f64;4];4];for i in 0..r as usize{for j in 0..d as usize{let z=x[2+i*d as usize+j];if !(-1000..=1000).contains(&z)||(j<i&&z!=0)||(j==i&&!(100..=1000).contains(&z)){return -1}a[i][j]=z as f64/1000.0;}}let bytes=(r*d*8)as usize;if out.is_null()||cap<bytes{return -2}for k in 0..r as usize{let mut p=[0.0f64;4];for i in 0..k{let(mut dot,mut norm)=(0.0,0.0);for j in 0..d as usize{dot+=a[k][j]*q[i][j];norm+=q[i][j]*q[i][j];}let f=dot/norm;for j in 0..d as usize{p[j]+=q[i][j]*f;}}for j in 0..d as usize{q[k][j]=a[k][j]-p[j];}}let b=std::slice::from_raw_parts_mut(out,bytes);for i in 0..r as usize{for j in 0..d as usize{put(b,(i*d as usize+j)*8,q[i][j]);}}bytes as i64}
